# Count ESCALATED_TO_HUMAN by role timeline
python3 << 'EOF'
import json
from collections import Counter, defaultdict
with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/logs/ralph_loop_timeline.jsonl') as f:
    events = [json.loads(l) for l in f if l.strip()]

# Escalations & hard limits
by_role = defaultdict(Counter)
for e in events:
    by_role[e['role']][e['event']] += 1

print("ESCALATED_TO_HUMAN by role:")
for role in ('director', 'agent', 'reviewer'):
    print(f"  {role}: {by_role[role].get('ESCALATED_TO_HUMAN', 0)}")

print("\nHARD_LIMIT_REACHED by role:")
for role in ('director', 'agent', 'reviewer'):
    print(f"  {role}: {by_role[role].get('HARD_LIMIT_REACHED', 0)}")

print("\nDIRECTOR_DECISION breakdown:")
dec_counter = Counter()
for e in events:
    if e['event'] == 'DIRECTOR_DECISION':
        dec_counter[e.get('details', {}).get('decision', '?')] += 1
for k,v in dec_counter.most_common():
    print(f"  {k}: {v}")

# Hard limit triggers
print("\nHARD_LIMIT triggers:")
trig = Counter()
for e in events:
    if e['event'] == 'HARD_LIMIT_REACHED':
        trig[(e['role'], e.get('details', {}).get('trigger', '?'))] += 1
for k,v in trig.most_common():
    print(f"  {k}: {v}")

# Time per role
print("\nFirst/last events per role:")
fl = defaultdict(lambda: [None, None])
for e in events:
    t = e['ts']
    if fl[e['role']][0] is None or t < fl[e['role']][0]:
        fl[e['role']][0] = t
    if fl[e['role']][1] is None or t > fl[e['role']][1]:
        fl[e['role']][1] = t
for r, (a, b) in fl.items():
    print(f"  {r}: {a} → {b}")

# Boots by date
print("\nBoots per day per role:")
boots_by_day = defaultdict(lambda: defaultdict(int))
for e in events:
    if e['event'] == 'BOOT_COMPLETE' and not e.get('details', {}).get('restart_recovery'):
        day = e['ts'][:10]
        boots_by_day[day][e['role']] += 1
for day in sorted(boots_by_day):
    print(f"  {day}: {dict(boots_by_day[day])}")
EOF

