# Look at sample director text content during M035 sign-reversal discovery
python3 << 'EOF'
import json
fp = '/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0514-4-projects-distrib-canary-collapse--claude-sessions-director-6dc4a1c8/9b13e0b0-83f5-487c-961e-91729cdc777d.jsonl'
target_keywords = ['sign reversal', 'sign-reversal', 'peak_lag', 'M035', 'D116', 'D117', 'M050']
samples = []
with open(fp) as f:
    for line in f:
        if not line.strip(): continue
        try:
            e = json.loads(line)
            if e.get('type') != 'assistant': continue
            msg = e.get('message', {})
            content = msg.get('content', [])
            text = ''
            for c in content:
                if isinstance(c, dict):
                    if c.get('type') == 'text':
                        text += c.get('text', '')
                    elif c.get('type') == 'tool_use':
                        # capture tool name & input
                        pass
            for kw in target_keywords:
                if kw in text:
                    samples.append((e.get('timestamp', ''), kw, text[:600].replace('\n', ' / ')))
                    break
        except Exception:
            pass
print(f'Samples: {len(samples)}')
for s in samples[:12]:
    print(' '.join(str(x) for x in s)[:1000])
    print('---')
EOF

# Look at the largest worker session to see what kind of failure modes happen
