import json
from collections import Counter
fp = '/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0514-4-projects-distrib-canary-collapse/c09a0915-3f1c-4063-b56c-05f0c0380b6f.jsonl'
events = []
with open(fp) as f:
    for line in f:
        if line.strip():
            try:
                events.append(json.loads(line))
            except: pass
print(f'Events: {len(events)}')
# Find first user message
for e in events[:10]:
    msg = e.get('message', {})
    if e.get('type') == 'user':
        content = msg.get('content', '') if isinstance(msg, dict) else ''
        if isinstance(content, str):
            print('FIRST USER (str):', content[:600])
            break
        elif isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get('type') in ('text', 'tool_result'):
                    txt = c.get('text', '') or c.get('content', '')
                    if isinstance(txt, str) and len(txt) > 50:
                        print(f'FIRST USER ({c.get("type")}):', txt[:600])
                        break
            break
# Count types
types = Counter([e.get('type') for e in events])
print('Type distribution:', dict(types))
# Tool usage
tools = Counter()
for e in events:
    if e.get('type') == 'assistant':
        msg = e.get('message', {})
        for c in msg.get('content', []) or []:
            if isinstance(c, dict) and c.get('type') == 'tool_use':
                tools[c.get('name','?')] += 1
print('Top tools used:')
for k,v in tools.most_common(15):
    print(f'  {k}: {v}')
EOF
